def transform(grid):
    # Fill each enclosed background component with the demo-matched parity color.
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = []
            edge = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or y == h-1 or x == 0 or x == w-1:
                    edge = True
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not edge:
                value = 7 if len(region) % 2 else 2
                for y, x in region:
                    out[y][x] = value
    return out

